def update_all():
    for wid, steps in WORKOUT_EXERCISES.items():
        steps_json = json.dumps(steps)
        execute("UPDATE workouts SET exercise_steps_json = %s WHERE id = %s", (steps_json, wid))
    print(f"Successfully updated all {len(WORKOUT_EXERCISES)} workouts in the database with custom, authentic exercise steps!")

if __name__ == "__main__":
    update_all()
